beginning.embedded_functions:
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include "mmt_lib.h"
#include "pre_embedded_functions.h"

// Define a structure to hold state information for each gNB
typedef struct {
    uint64_t last_ngsetuprequest_time;
    int request_count;
} gnb_state_t;

// Global array to store gNB state.  Indexed by source IP.
gnb_state_t gnb_states[65536]; // Assuming 16-bit source IP.  Adjust size as needed.

void on_load() {
    // Initialize all gNB states to zero.
    for (int i = 0; i < 65536; i++) {
        gnb_states[i].last_ngsetuprequest_time = 0;
        gnb_states[i].request_count = 0;
    }
    mmt_info("NG Setup Storm Detection: Loaded and initialized gNB states.");
}

// Embedded function to check if the rate of NGSetupRequest messages exceeds the threshold.
static inline bool em_check_ngsetuprequest_rate(const void *data) {
    struct ngap_ngsetuprequest_t *ngsetuprequest = (struct ngap_ngsetuprequest_t *)data;
    uint64_t src_ip = ngsetuprequest->src_ip_addr; // Assuming ngsetuprequest has src_ip_addr field. Adapt if different.

    if (gnb_states[src_ip].request_count >= 5) {
        return true; // Threshold exceeded
    }

    return false;
}

//Embedded function to increment the counter and timestamp for each request
static inline void em_increment_ngsetuprequest_count(const void *data){
    struct ngap_ngsetuprequest_t *ngsetuprequest = (struct ngap_ngsetuprequest_t *)data;
    uint64_t src_ip = ngsetuprequest->src_ip_addr;
    gnb_states[src_ip].request_count++;
    gnb_states[src_ip].last_ngsetuprequest_time = mmt_get_timestamp();
}
